<?php foreach (($liveNow ?? []) as $v): ?><div class="alert alert-success d-flex flex-wrap align-items-center gap-2 shadow-sm" role="status"><span class="spinner-grow spinner-grow-sm text-success" aria-hidden="true"></span><div class="flex-grow-1"><strong><?= $v['state'] === 'live' ? 'حصة مباشرة الآن' : 'تبدأ بعد قليل' ?>:</strong> <?= e($v['title']) ?> <small class="text-muted">— <?= e($v['subject_name']) ?></small></div>
